const targets = `-- name: Targets :many
SELECT id, user_id, host_id, name, instance_id, generation, desired, phase, observed_generation, spec, cpu_millis, memory_bytes, usage, reason, billing_stop_reason, observed_at, created_at, updated_at FROM environments WHERE host_id=$1 AND id>$2::uuid
AND NOT(desired='deleted' AND phase='deleted' AND observed_generation=generation)
ORDER BY id LIMIT 16
`

type TargetsParams struct {
	HostID string `json:"host_id"`
	Cursor string `json:"cursor"`
}

func (q *Queries) Targets(ctx context.Context, arg TargetsParams) ([]Environment, error) {
	rows, err := q.db.Query(ctx, targets, arg.HostID, arg.Cursor)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Environment{}
	for rows.Next() {
		var i Environment
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.HostID,
			&i.Name,
			&i.InstanceID,
			&i.Generation,
			&i.Desired,
			&i.Phase,
			&i.ObservedGeneration,
			&i.Spec,
			&i.CpuMillis,
			&i.MemoryBytes,
			&i.Usage,
			&i.Reason,
			&i.BillingStopReason,
			&i.ObservedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

